import asyncio, re
from playwright.async_api import async_playwright
URL="http://localhost:8790/dist/local.html"
R=[]
def rec(n, ok, note=""): R.append(ok); print(("PASS " if ok else "FAIL ")+n+(" — "+note if note else ""))
async def main():
  async with async_playwright() as pw:
    b=await pw.chromium.launch(); ctx=await b.new_context(viewport={"width":1280,"height":900}); p=await ctx.new_page()
    errs=[]; p.on("pageerror", lambda e: errs.append(str(e)))
    await p.goto(URL); await p.evaluate("localStorage.clear()"); await p.reload(); await p.wait_for_timeout(1200)
    B=p.locator('[data-app=buyer]'); S=p.locator('[data-app=seller]')
    async def login(ph, label=None, phone=None):
      if label: await ph.get_by_role("button", name=re.compile(label)).first.click()
      else: await ph.get_by_placeholder("10-digit mobile number").fill(phone)
      await ph.get_by_role("button", name="Send code").click(); await ph.locator("input.otp").fill("123456"); await ph.get_by_role("button", name="Verify and continue").click(); await p.wait_for_timeout(300)
    async def back_all(ph):
      for _ in range(6):
        if await ph.locator(".page").count()==0: break
        await ph.locator(".page").last.get_by_role("button", name="Back", exact=True).click(); await p.wait_for_timeout(120)
    async def tab(ph, name): await back_all(ph); await ph.locator(".tab", has_text=name).click(); await p.wait_for_timeout(200)
    # ---- New seller onboarding with payment step
    await login(S, phone="9811112222")
    await S.get_by_role("button", name=re.compile("Individual seller")).click()
    await S.locator("#so-ownerName").fill("Sana Khan"); await S.locator("#so-name").fill("Sana Studio"); await S.locator("#so-area").fill("Tolichowki")
    await S.get_by_role("button", name="Continue").click(); await p.wait_for_timeout(200)
    rec("Onboarding step 2: payment details", await S.get_by_text("How will buyers pay you?").count()==1)
    await S.get_by_role("button", name="Continue").click(); await p.wait_for_timeout(150)
    rec("Requires at least one payment method", await S.get_by_text("Add at least one way").count()==1)
    await S.locator("#sop-upiId").fill("sana-studio"); await S.get_by_role("button", name="Continue").click(); await p.wait_for_timeout(150)
    rec("Invalid UPI ID rejected", await S.get_by_text("Enter a UPI ID like").count()==1)
    await S.locator("#sop-upiId").fill("sana.studio@okaxis"); await S.locator("#sop-bankAccount").fill("12345"); await S.get_by_role("button", name="Continue").click(); await p.wait_for_timeout(150)
    rec("Partial bank details rejected", await S.get_by_text("Enter the account holder").count()==1 and await S.get_by_text("11-character IFSC").count()==1)
    await S.locator("#sop-bankAccount").fill(""); await S.get_by_role("button", name="Continue").click(); await p.wait_for_timeout(200)
    await S.get_by_role("button", name="Agree and register").click(); await p.wait_for_timeout(300)
    rec("New seller registered", await S.locator(".tabbar").count()==1)
    await tab(S, "Shop")
    st = await S.inner_text(); rec("Shop shows payment details (masked) and order record", "sana.studio@okaxis" in st and "No orders yet" in st)
    await S.get_by_role("button", name="Sign out").click(); await p.wait_for_timeout(200)
    # ---- Direct pay journey
    await login(S, "Indigo Threads"); await login(B, "Aarav Sharma")
    await tab(B, "Search"); await B.get_by_placeholder(re.compile("Search kurtas")).fill("hand-block"); await B.locator(".tile").first.click(); await p.wait_for_timeout(200)
    t = await B.inner_text(); rec("Product shows direct-pay info", "Pay the seller directly" in t and "UPI" in t and "Bank transfer" in t)
    rec("No payment details on product page", "okhdfcbank" not in t and "50200012345678" not in t)
    await B.locator(".page .chip", has_text=re.compile(r"^M$")).click(); await B.get_by_role("button", name="Make offer").click()
    await B.locator("#offer-amt").fill("1950"); await B.get_by_role("button", name=re.compile("Send offer")).click(); await p.wait_for_timeout(1500)
    rec("No instant counter: buyer waits for the seller", "Waiting for the seller" in await B.inner_text() and await B.get_by_role("button", name="Buy at ₹2,299").count()==0)
    await p.wait_for_timeout(5000)
    bt = await B.inner_text()
    rec("Counter appears after ~5 s as plain 'Seller’s counter'", "Seller countered ₹2,299" in bt and "automatic" not in bt.lower())
    await B.get_by_role("button", name="Counter", exact=True).click(); await B.locator("input[id^=counter-]").fill("2100"); await B.get_by_role("button", name="Send counter").click(); await p.wait_for_timeout(6500)
    rec("Repeat counter for second offer below minimum", (await B.inner_text()).count("₹2,299") >= 3)
    await B.get_by_role("button", name="Buy at ₹2,299").click(); await p.wait_for_timeout(300)
    await B.get_by_role("button", name=re.compile("Continue · ₹2,299")).click(); await p.wait_for_timeout(200)
    rec("Place order needs a payment method", await B.get_by_role("button", name=re.compile("Place order")).is_disabled())
    await B.locator(".choice", has_text="Bank transfer").click(); await B.get_by_role("button", name=re.compile("Place order")).click(); await p.wait_for_timeout(300)
    ot = await B.inner_text(); m = re.search(r"Order (FY-\d+)", ot); num = m.group(1) if m else "?"
    rec("Buyer sees bank details + order note after placing", "50200012345678" in ot and "HDFC0001234" in ot and num in ot and "Awaiting payment confirmation" in ot, num)
    rec("Buyer has no confirm/advance controls", await B.get_by_role("button", name=re.compile("Payment received|Mark delivered|I.ve paid")).count()==0)
    await tab(S, "Orders"); await S.locator(".listrow", has_text=num).click(); await p.wait_for_timeout(200)
    await S.get_by_role("button", name="Payment received").click(); await S.get_by_text("Add shipment details now").click()
    await S.locator("#cs-trackingUrl").fill("http://not-secure"); await S.get_by_role("button", name="Confirm and add shipment").click(); await p.wait_for_timeout(200)
    rec("Shipment link validated", await S.get_by_text("full https:// tracking link").count()==1)
    await S.locator("#cs-carrier").fill("Delhivery"); await S.locator("#cs-trackingId").fill("AWB998877"); await S.locator("#cs-trackingUrl").fill("https://track.example.com/AWB998877")
    await S.get_by_role("button", name="Confirm and add shipment").click(); await p.wait_for_timeout(300)
    bt = await B.inner_text()
    rec("Buyer sees Shipped + tracking, payment details hidden", "Shipped" in bt and "AWB998877" in bt and "50200012345678" not in bt)
    await S.get_by_role("button", name="Mark delivered").click(); await p.wait_for_timeout(300)
    rec("Delivered: buyer timeline complete", await B.locator(".status-steps .st.done").count()==4)
    # ---- Website seller journey (seeded saree counter with discount link)
    await tab(B, "Offers"); await B.locator(".listrow", has_text="saree").click(); await p.wait_for_timeout(200)
    rec("Website counter link hidden before acceptance", "deal=fy6199" not in await B.inner_html())
    await B.get_by_role("button", name="Buy at ₹6,199").click(); await p.wait_for_timeout(300)
    link = B.get_by_role("link", name=re.compile("Open discounted link"))
    href = await link.get_attribute("href"); rec("Accepted → discount link revealed", href and "deal=fy6199" in href, href)
    async with ctx.expect_page() as newp: await link.click()
    np = await newp.value; await np.close(); await p.wait_for_timeout(400)
    wt = await B.inner_text(); m = re.search(r"Order (FY-\d+)", wt); wnum = m.group(1) if m else "?"
    rec("Website order record created, awaiting seller", "Awaiting seller confirmation" in wt, wnum)
    await tab(S, "Shop"); await S.get_by_role("button", name="Sign out").click(); await login(S, "Loom & Co.")
    await tab(S, "Orders"); await S.locator(".listrow", has_text=wnum).click(); await p.wait_for_timeout(200)
    st = await S.inner_text(); rec("Seller sees website order without address", "enters the delivery address on your website" in st)
    await S.get_by_role("button", name="Order received").click(); await S.get_by_role("button", name="Confirm", exact=True).click(); await p.wait_for_timeout(300)
    rec("Website order confirmed (no shipment needed)", "Confirmed" in await B.inner_text())
    # ---- Website listing creation with codes
    await tab(S, "Listings"); await S.get_by_role("button", name="New listing").first.click(); await p.wait_for_timeout(200)
    rec("Web-only seller defaults to website checkout", await S.get_by_role("button", name="My website").get_attribute("aria-pressed")=="true")
    await S.get_by_role("button", name=re.compile("Use sample artwork")).click(); await S.locator("#le-title").fill("Ikat cotton dupatta")
    stocks = S.get_by_label(re.compile("Stock for"))
    for i in range(await stocks.count()): await stocks.nth(i).fill("2")
    await S.locator("#le-price").fill("1500"); await S.locator("#le-url").fill("https://loomandco.example.com/products/ikat-dupatta"); await S.locator("#le-a").fill("1300")
    await S.get_by_role("button", name="Publish").click(); await p.wait_for_timeout(200)
    rec("Auto-accept on website requires a code", await S.get_by_text("Code for your automatic price").count()>0)
    await S.locator("#le-acode").fill("dupatta1300"); await S.get_by_role("button", name="Publish").click(); await p.wait_for_timeout(300)
    rec("Website listing published", await S.get_by_text("Sold on your website").count()==1)
    await tab(B, "Search"); await B.get_by_placeholder(re.compile("Search kurtas")).fill("ikat cotton"); await B.locator(".tile").first.click(); await p.wait_for_timeout(200)
    rec("Buyer sees Buy on website", await B.get_by_role("link", name=re.compile("Buy on website")).count()==1)
    await B.locator(".page .chip").filter(has_text=re.compile(r"^M$")).click(); await B.get_by_role("button", name="Make offer").click()
    await B.locator("#offer-amt").fill("1400"); await B.get_by_role("button", name=re.compile("Send offer")).click(); await p.wait_for_timeout(300)
    t = await B.inner_text(); rec("Offer ≥ ₹1,300 auto-agreed at code price with code shown", "Deal agreed: ₹1,300" in t and "DUPATTA1300" in t)
    # ---- Seller manual accept on website requires code
    await back_all(B); await B.get_by_placeholder(re.compile("Search kurtas")).fill("linen co-ord"); await B.locator(".tile").first.click(); await B.locator(".page .chip").filter(has_text=re.compile(r"^S$")).click(); await B.get_by_role("button", name="Make offer").click()
    await B.locator("#offer-amt").fill("2600"); await B.get_by_role("button", name=re.compile("Send offer")).click(); await p.wait_for_timeout(300)
    await tab(S, "Offers"); await S.locator(".listrow", has_text="Linen").first.click(); await p.wait_for_timeout(200)
    await S.get_by_role("button", name="Accept ₹2,600").click(); await S.get_by_role("button", name="Accept and send to buyer").click(); await p.wait_for_timeout(150)
    rec("Manual accept on website needs code", await S.get_by_text(re.compile("enter a coupon code or a discount link")).count()==1)
    await S.locator("#acc-deal").fill("AARAV2600"); await S.get_by_role("button", name="Accept and send to buyer").click(); await p.wait_for_timeout(300)
    rec("Buyer receives seller's manual code", "AARAV2600" in await B.inner_text())
    # ---- Expiry of unconfirmed direct order
    await tab(S, "Shop"); await S.get_by_role("button", name="Sign out").click(); await login(S, "Indigo Threads")
    await tab(B, "Search"); await B.get_by_placeholder(re.compile("Search kurtas")).fill("dabu"); await B.locator(".tile").first.click(); await B.get_by_role("button", name=re.compile("Buy now")).click(); await p.wait_for_timeout(200)
    await B.locator(".choice", has_text="UPI").first.click(); await B.get_by_role("button", name=re.compile("Place order")).click(); await p.wait_for_timeout(300)
    up = await B.get_by_role("link", name=re.compile("in a UPI app")).get_attribute("href")
    rec("UPI deep link prefilled with amount and order note", up.startswith("upi://pay?pa=indigothreads%40okhdfcbank") and "am=1299.00" in up and "tn=FY-" in up, up[:80])
    for _ in range(4): await p.get_by_role("button", name="+12 h").click(); await p.wait_for_timeout(150)
    await p.wait_for_timeout(1200)
    rec("Unconfirmed order expires after 48 h", "Expired" in await B.inner_text())
    await back_all(B); await B.locator(".tile").first.click(); await p.wait_for_timeout(200)
    rec("Seller record shows the unconfirmed order", "unconfirmed" in await B.inner_text())
    await p.screenshot(path="/home/claude/shots/e2e2-end.png")
    rec("No page errors", not errs, "; ".join(errs[:3]))
    print(f"\n{sum(R)}/{len(R)} passed"); await b.close()
asyncio.run(main())
